INSERT INTO items (id, code, name, category, group1, group2, cert_type, base_standard, scope_text, source_doc, source_page, source_edition, needs_standard_text, extraction) VALUES
(1001, 'E-0001', '절연전선', 'electric', '전선 및 전원코드', '전선, 케이블 및 코드류', 'safety_cert', 'KC 60227-1, 정격전압 450/750 V 이하의 염화비닐 절연케이블 제1부 : 일반 요구사항 / KC 60227-2, 정격전압 450/750 V 이하의 염화비닐 절연케이블 제2부 : 시험방법 / KC 60227-3, 정격전압 450/750 V 이하의 염화비닐 절연케이블 제3부 : 배선용 절연전선 / KC 60245-1, 정격전압 450/750 V 이하의 고무절연 케이블, 제1부 : 일반요구사항 / KC 60245-2, 정격전압 450/750 V 이하의 고무절연 케이블, 제2부 : 시험방법 / KC 60245-3, 정격전압 450/750 V 이하의 고무절연 케이블, 제3부 : 내연 실리콘 고무절연케이블', '공칭전압 교류 450/750 V 이하의 전기설비 등에 사용하는 폴리염화비닐수지 및 고무를 주성분으로 하는 절연체를 피복한 것으로 주로 옥내단심 내열성 에틸렌 비닐 아세테이트 고무 절연 전선용으로 사용되는 것으로 공칭단면적이 95 mm² 이하인 것으로 한정한다.', '전기용품 표시사항 작성 가이드북', 20, '가이드북 2021-11', 0, 'auto'),
(1002, 'E-0002', '연질 비닐 시스 케이블', 'electric', '전선 및 전원코드', '전선, 케이블 및 코드류', 'safety_cert', 'KC 60227-1, 정격전압 450/750 V 이하의 염화비닐 절연케이블 제1부 : 일반 요구사항 / KC 60227-4, 정격전압 450/750 V 이하의 염화비닐 절연케이블 제4부 : 고정배선용 시스케이블 / KC 60227-6, 정격전압 450/750 V 이하의 염화비닐 절연케이블 제6부 : 리프트 케이블과 연결용 유연성 케이블 / KC 60227-7, 정격전압 450/750 V 이하의 염화비닐 절연케이블 제7부 : 2심 또는 다심의 차폐 및 차폐 유연성 케이블 / KC 60245-1, 정격전압 450/750 V 이하의 고무절연 케이블, 제1부 : 일반요구사항 / KC 60245-4, 정격전압 450/750 V 이하의 고무절연 케이블, 제4부 : 코드 및 가요케이블 / KC 60245-5, 정격전압 450/750 V 이하의 고무절연 케이블, 제5부 : 리프트케이블 / KC 60245-6, 정격전압 450/750 V 이하의 고무절연 케이블, 제6부 : 아크용접용 케이블 / KC 60245-7, 정격전압 450/750 V 이하의 고무절연 케이블, 제7부 : 내열성 에틸렌 비닐아세테이트 고무 절연전선 / KC 60502-1, 정격전압 1 kV(Um=1.2 ', '2가닥 이상 꼬거나 평형 상태로 하여 고무 등으로 피복한 것을 말하며 개재물로서 종이나 실 등을 넣은 것도 있으며 공칭단면적이 95 mm² 이하인 것으로 한정한다.', '전기용품 표시사항 작성 가이드북', 21, '가이드북 2021-11', 0, 'auto'),
(1003, 'E-0003', '범용 비닐 시스 코드', 'electric', '전선 및 전원코드', '전선, 케이블 및 코드류', 'safety_cert', 'KC 60227-1, 정격전압 450/750 V 이하의 염화비닐 절연케이블 제1부 : 일반 요구사항 / KC 60227-5, 정격전압 450/750 V 이하의 염화비닐 절연케이블 제5부 : 가요케이블(코드) / KC 60245-1, 정격전압 450/750 V 이하의 고무절연 케이블, 제1부 : 일반요구사항 / KC 60245-4, 정격전압 450/750 V 이하의 염화비닐 절연케이블 제4부 : 코드 및 가요 케이블 / KC 60245-8, 정격전압 450/750 V 이하의 고무절연 케이블, 제8부 : 고 유연성 전기기기용 코드', '주로 전동기구나 전기기기의 전원전선으로 사용되는 것으로서 자유로운 이동이 가능하도록 소선이 가늘고 유연한 것으로 구성되어 있으며 공칭단면적이 0.5 mm² 이상 6 mm² 이하인 것에 한정한다.', '전기용품 표시사항 작성 가이드북', 22, '가이드북 2021-11', 0, 'auto'),
(1004, 'E-0004', '염화 비닐 절연 케이블', 'electric', '전선 및 전원코드', '전선, 케이블 및 코드류', 'safety_cert', 'KC 60799, 전기용 부속품 – 코드셋 및 상호연결 코드셋', '전기기기 또는 장치의 전원에 접속을 목적으로 코드 비교환형 플러그와 코드 비교환형 커넥터에 코드를 장착한 것이다. ▪ 표시', '전기용품 표시사항 작성 가이드북', 23, '가이드북 2021-11', 0, 'auto'),
(1005, 'E-0005', '일반스위치(마이크로스위치)', 'electric', '전기기기용 스위치', '스위치', 'safety_cert', 'KC 61058-1, 기기용 스위치 제1부 : 일반요구사항', '전기기기 및 기타 장치를 작동 또는 제어하기 위하여 손, 발 또는 기타 인간의 동작에 의해 움직여지는 스위치를 말하며, 정격전압 480 V 이하, 정격전류가 30 A 이하인 것에 한정한다.', '전기용품 표시사항 작성 가이드북', 24, '가이드북 2021-11', 1, 'auto'),
(1006, 'E-0006', '전기설비용 스위치', 'electric', '전기기기용 스위치', '스위치', 'safety_cert', 'KC 60669-1, 가정용 및 이와 유사한 용도의 고정 전기 설비용 스위치 제1부 : 일반요구사항', '가정용 및 이와 유사한 용도의 고정 전기설비에 장착하는 교류 전용 수동식 범용 스위치로 정격 전압 440 V 이하, 정격 전류 63 A 이하의 옥내용 또는 옥외용 전기설비에 적용하는 것을 말한다. 나사 없는 단자가 달린 스위치의 정격 전류는 16 A를 한도로 한다.', '전기용품 표시사항 작성 가이드북', 25, '가이드북 2021-11', 0, 'auto'),
(1007, 'E-0007', '코드스위치', 'electric', '전기기기용 스위치', '스위치', 'safety_cert', 'KC 61058-1, 기기용 스위치 제1부 : 일반요구사항 / KC 61058-2-1, 기기용 스위치 제2-1부 : 코드스위치의 개별 요구사항', '유연한 케이블로 전원 및 기기 또는 장치에 접속하도록 의도된 기기로 폐쇄된 스위치이자 코드선에 연결되어 사용되는 스위치로서 250 V 이하, 16 A 이하인 것에 한정한다. ▪ 스위치의 식별', '전기용품 표시사항 작성 가이드북', 26, '가이드북 2021-11', 0, 'auto'),
(1008, 'E-0008', '전자식 스위치', 'electric', '전기기기용 스위치', '스위치', 'safety_cert', 'KC 60669-1, 가정용 및 이와 유사한 용도의 고정 전기 설비용 스위치 제1부 : 일반요구사항 / KC 60669-2-1, 가정용 및 이와 유사한 용도의 고정 전기 설비용 스위치 제2-1부 : 전기스위치의 개별요구사항', '가정용 및 이와 유사한 용도의 고정 전기설비에 장착하는 전자 스위치와 이와 관련하는 전자식 스위치로 옥내용 또는 옥외용 전기설비에 사용하는 스위치이다. 램프 회로 조작용, 램프의 조도 제어(조광기)용, 모터(예를 들면 환기팬에서 사용되는 것)의 속도 제어용, 모터 회로 조작용, 그리고 기타 목적(예를 들면 난방 설비)을 위한 전자 스위치로 교류사용 전압 250 V 이하, 정격 전류 16 A 이하인 전기설비에 적용되는 것이다. ▪ 정격 전압', '전기용품 표시사항 작성 가이드북', 27, '가이드북 2021-11', 0, 'auto'),
(1009, 'E-0009', '리모트콘트롤스위치', 'electric', '전기기기용 스위치', '스위치', 'safety_cert', 'KC 60669-1, 가정용 및 이와 유사한 용도의 고정 전기 설비용 스위치 제1부 : 일반요구사항 / KC 60669-2-2, 가정용 및 이와 유사한 용도의 고정 전기 설비용 스위치 / 제2부 : 개별요구사항 제2절 : 리모트 콘트롤 스위치(R.C.S)', '가정용 및 이와 유사한 용도의 고정 전기설비의 옥내용 및 옥외용의 전자식 원격제어용스위치(Remote Control Switch, RCS)를 말하며, 정격전압 440 V 이하, 정격전류가 63 A 이하인 것에 한정한다. ▪ 정격 전류(A) 또는 정격 형광등 부하 전류(AX)나 2개의', '전기용품 표시사항 작성 가이드북', 28, '가이드북 2021-11', 0, 'auto'),
(1010, 'E-0010', '시간지연 스위치', 'electric', '전기기기용 스위치', '스위치', 'safety_cert', 'KC 60669-1, 가정용 및 이와 유사한 용도의 고정 전기 설비용 스위치 제1부 : 일반요구사항 / KC 60669-2-3, 가정용 및 이와 유사한 용도의 고정 전기 설비용 스위치 제2-3부 : 지연스위치 개별요구사항', '가정용 및 이와 유사한 용도의 고정 전기설비에 장착하는 시간지연 스위치(Time Delay Switch, T.D.S.)로 정격 전압이 440 V 이하 정격 전류가 63 A 이하인 손 또는 원격 제어로 조작되고 기계, 열, 기압, 수압 혹은 전기 또는 이들 중의 어느 것을 조합하여 구동하는 지연 장치를 갖고 있는 전기설비에 적용하는 것을 말한다. ▪ 정격 전류(A) 또는 정격 형광등 부하 전류(AX)나 2개의 · 제조년월 : 2020년 10월 다른 정격을 조합하였을 경우에는 양쪽 조합의 정격 ▪ 정격 전압(볼트): 정격 전압과 다를 경우 정격 제어 전압(볼트) ▪ 제조사 명, 판매자 명, 상호 또는 식별 기호 ▪ 부하의 형식 ▪ 보호 정도 ▪ 외부 도체 접속에 대한 단자 ▪ 헤드의 온도 한계치 ▪ 설치면의 온도 한계치 ▪ II등급 구조의 기호 ▪ 지연 시간의 조정 변화에 대한 기호 ▪ “향상 켜짐”과 “향상 꺼짐”의 위치 기호 ▪ “지연 시간”의 기호 ▪ 단자 기호가 표시된 배선도를 부착 · 제조자명(수입자명) : 한국제품안전협회 ▪ 표시, 사용설명서 및 주의사항', '전기용품 표시사항 작성 가이드북', 29, '가이드북 2021-11', 0, 'auto'),
(1011, 'E-0011', '조광기', 'electric', '전기기기용 스위치', '스위치', 'safety_cert', 'KC 60669-1, 가정용 및 이와 유사한 용도의 고정 전기 설비용 스위치 제1부 : 일반요구사항 / KC 60669-2-1, 가정용 및 이와 유사한 용도의 고정 전기 설비용 스위치 제2-1부 : 전기스위치의 개별요구사항', '램프의 조도제어용 스위치를 말하며, 정격전압 250 V 이하, 정격전류가 16 A 이하인 것에 한정한다. ▪ 볼트 표기의 정격 전압 ▪ 암페어 표기의 정격 전류 또는 볼트 암페어 또는 와트 표기의', '전기용품 표시사항 작성 가이드북', 30, '가이드북 2021-11', 0, 'auto'),
(1012, 'E-0012', '제어회로용 스위치', 'electric', '전기기기용 스위치', '스위치', 'safety_cert', 'KC 60947-1, 가정용 및 이와 유사한 설비에 사용되는 과전류 보호용 차단기 : 교류용 차단기 / KC 60947-5-1, 저압개폐장치 및 제어장치 제5-1부 : 제어회로 소자 및 개폐소자 - 전기기계적 제어회로 소자', '정격전압 480 V 이하, 정격전류가 30 A 이하인 것에 한정한다. ▪ 제조자의 이름 또는 상표', '전기용품 표시사항 작성 가이드북', 31, '가이드북 2021-11', 0, 'auto'),
(1013, 'E-0013', '전자개폐기', 'electric', '전기기기용 스위치', '전자개폐기', 'safety_cert', 'KC 60947-2, 저압개폐장치 및 제어장치 제2부 : 차단기 / KC 60947-4-1, 저전압 개폐장치 및 제어장치 제4-1부 : 접촉기 및 모터 기동기 – 전자식 접촉기 및 모터기동기 / KC 61095, 가정용과 유사 용도를 위한 전기 기계적 접촉자', '전자접촉기의 ON/OFF에 의해 모터 등의 부하를 운전/정지시킴으로써 부하를 보호 및 제어하는 목적으로 사용되고, 과부하계전기에 의해 부하에 일정 이상의 과전류가 흐르면 이를 감지하여 전자접촉기의 조작전원을 OFF시켜 부하를 정지시키며, 전자접촉기와 과부하계전기가 조합되어 사용되는 것으로 정격전류가 300 A 이하인 것에 한정한다. ▪ 다음 데이터들은 차단기 본체 또는 차단기에 부착된 명판에 표기되어야 하고,', '전기용품 표시사항 작성 가이드북', 32, '가이드북 2021-11', 0, 'auto'),
(1014, 'E-0014', '커패시터 및 전원필터', 'electric', '전원용 커패시터 및 전원필터', '커패시터 및 전원필터', 'safety_cert', 'KC 60384-1, 전자기기용 고정 캐피시터 제1부 : 일반 요구사항 / KC 60384-14, 전자기기용 고정 커패시터 제14부 : 전기자기 장해 억제 및 주전원 연결용 커패시터', '전자파 장해 방지용으로 교류전원의 입력 단에 연결되어 쓰이는 커패시터를 말한다. 도체간의 전압이 500 V 이하이거나 도체와 접지간의 전압이 250 V 이하인 것 또는 저항 커패시터가 조합되어 결합되어진 것으로 등가회로의 직렬저항 값이 1 ㏀ 이하인 것에 한정한다.', '전기용품 표시사항 작성 가이드북', 33, '가이드북 2021-11', 0, 'auto'),
(1015, 'E-0015', '커패시터 및 전원필터', 'electric', '전원용 커패시터 및 전원필터', '커패시터 및 전원필터', 'safety_cert', 'KC 60939-1, 전자파방해 방지용 필터소자 제1부 : 일반 요구사항 / KC 60939-2, 전자파방해 방지용 필터소자 제2부 : 시험방법의 선택과 일반사항', '전자파 장해 방지용으로 교류전원의 입력 단에 연결되어 쓰이는 전원필터로서 도체간 공칭전압이 500 V 또는 도체와 접지간의 전압이 250 V 이하인 것에 한정한다. ▪ 제조자의 이름(또는 상표)', '전기용품 표시사항 작성 가이드북', 34, '가이드북 2021-11', 0, 'auto'),
(1016, 'E-0016', '커패시터 및 전원필터', 'electric', '전원용 커패시터 및 전원필터', '커패시터 및 전원필터', 'safety_cert', 'KC 61048, 램프 보조장치 형광등 램프 및 방전램프용 커패시터 - 일반 및 안전 / KC 61049, 형광등과 방전램프 회로에 쓰이는 캐패시터 – 성능에 관한 요구사항', '방전램프 회로에 사용되는 자기복원 및 비-자기복원 커패시터로 용량이 0.1 μF 이상이고 무효전력이 2.5 kvar 이하인 형광등용인 것에 한정한다. ▪ 정격용량과 허용오차', '전기용품 표시사항 작성 가이드북', 35, '가이드북 2021-11', 0, 'auto'),
(1017, 'E-0017', '상호연결커플러(커넥터)', 'electric', '전기설비용 부속품 및 연결부품', '전기설비용 부속품 및 연결부품', 'safety_cert', '[전기설비용 부속품 및 연결부품]', 'KC 60320-1, 가정용 및 유사용도의 기기용 커플러 제1부 : 일반요구사항 KC 60065, 오디오･비디오기기 및 이와 유사한 전기기기의 안전 배선과 코드의 접속 또는 코드 상호간에 접속 사용하는 전기설비용 부속품 및 연결부품으로 전원분배기 포함한다.', '전기용품 표시사항 작성 가이드북', 36, '가이드북 2021-11', 1, 'auto'),
(1018, 'E-0018', '상호연결 커플러(기기용인렛 / 커넥터)', 'electric', '전기설비용 부속품 및 연결부품', '전기설비용 부속품 및 연결부품', 'safety_cert', '[전기설비용 부속품 및 연결부품]', 'KC 60320-1, 가정용 및 유사용도의 기기용 커플러 제1부 : 일반요구사항 KC 60320-2-1, 가정용 및 이와 유사한 용도의 기기용 커플러 제 2-1부 : 재봉기커플러 K 60320-2-2, 가정용 및 이와 유사한 용도의 기기용 커플러 제 2-2부 : 가정용 및 유사설비의 상호연결 커플러 KC 60320-2-3, 가정용 및 이와 유사한 용도의 기기용 커플러 제 2-3부 : 보호 등급이 IPX0이상인 기기용 커플러 상호연결 커플러(appliance coupler)는 가정용 및 이와 유사한 용도로 전원용 전기 기기 또는 기타 전기 장치와 전원용 코드를 접속하기 위한 것이다. 정격전압 250 V 이하, 정격전류 16 A 이하의 접지극이 있거나 접지극이 없는 것에 한정한다.', '전기용품 표시사항 작성 가이드북', 37, '가이드북 2021-11', 0, 'auto'),
(1019, 'E-0019', '플러그 / 콘센트', 'electric', '전기설비용 부속품 및 연결부품', '전기설비용 부속품 및 연결부품', 'safety_cert', '[전기설비용 부속품 및 연결부품]', 'KC 60884-1, 가정용 및 이와 유사한 용도의 플러그와 콘센트 제1부 : 일반요구사항 KC 60884-2-1, 가정용 및 이와 유사한 용도의 플러그와 콘센트 제2-1부 : 퓨즈형 플러그의 개별 요구사항 KC 60884-2-2, 가정용 및 이와 유사한 용도의 플러그와 콘센트 제2-2부 : 기기용 콘센트의 개별 요구사항 KC 60884-2-3, 가정용 및 이와 유사한 용도의 플러그와 콘센트 제2-3부 : 고정 배선용 인터록이 없는 스위치형 콘센트의 개별 요구사항 KC 60884-2-4, 가정용 및 이와 유사한 용도의 플러그와 콘센트 제2-4부 : SELV의 플러그와 콘센트의 개별 요구사항 KC 60884-2-5, 가정용 및 이와 유사한 용도의 플러그와 콘센트 제2-5부 : 어댑터의 개별 요구사항 KC 60884-2-6, 가정용 및 이와 유사한 용도의 플러그와 콘센트 제2-6부 : 고정 배선용 인터록 스위치형 콘센트의 개별 요구사항 K 10026, 대기전력 자동 차단 콘센트 정격 전압이 50 V 이상 440 V 이하이고 정격 전류가 32 A 이하인 접지극 유/무의 옥내/옥외용으로 사용되는 가정용 및 이와 유사한 용도의 교류 전용 플러그와 콘센트 또는 이동형 콘센트를 말한다. ▪ 접속 기구류는 다음과 같이 표시된다.', '전기용품 표시사항 작성 가이드북', 38, '가이드북 2021-11', 0, 'auto'),
(1020, 'E-0020', '케이블릴', 'electric', '전기설비용 부속품 및 연결부품', '전기설비용 부속품 및 연결부품', 'safety_cert', '[전기설비용 부속품 및 연결부품]', 'KC 61242, 전기용부속품 – 가정용 및 이와 유사한 용도의 케이블릴 릴에 부착된 유연 케이블과 코드로 이루어지는 장치로 단상 정격전압 250 V 정격전류 16 A 이하, 삼상 정격전압 440 V 정격전류 16 A 이하인 것에 한정한다.', '전기용품 표시사항 작성 가이드북', 39, '가이드북 2021-11', 0, 'auto'),
(1021, 'E-0021', '퓨즈', 'electric', '전기용품보호용 부품', '퓨즈', 'safety_cert', 'K 60127-1, 소형 퓨즈 제1부: 소형 퓨즈의 정의 및 소형 퓨즈링크의 일반 요구사항 / KC 60127-2, 소형 퓨즈 제2부: 통형 퓨즈링크 / KC 60127-3, 소형 퓨즈 제3부: 초소형 퓨즈링크 / KC 60127-4, 소형 퓨즈 제4부: 유니버셜 모듈 퓨즈링크 / KC 60127-6, 소형 퓨즈 제6부: 소형 퓨즈링크용 퓨즈홀더', '전기제품 또는 그 부품들을 과전류로부터 보호하기 위하여 사용되는 것으로서 가용체의 재료는 납, 주석, 아연 또는 이 들을 주성분으로 한 합금으로서, 전류가 정해진 시간 이상동 안 제시된 값을 초과할 때 특별히 고안된 부분 중 하나 또는 여러 개를 녹임으로써 회로를 개방시키도록 만들어진 장치이다. 정격전류가 20 mA 이상 10 A 이하인 것에 한정한다.', '전기용품 표시사항 작성 가이드북', 40, '가이드북 2021-11', 1, 'auto'),
(1022, 'E-0022', '온도퓨즈', 'electric', '전기용품보호용 부품', '퓨즈', 'safety_cert', 'KC 60691, 온도퓨즈 – 요구사항 및 적용지침', '금속성분이 일정한 경우 융점이 변화되지 않는 원리를 이용한 것으로 실내 사용의 전기제품, 전자장비와 부속품에 결합되어 이상 상태 시 과다한 온도에 노출되는 것을 막기 위해 회로를 차단하는 재설정이 불가능의 장치이다. 동작온도가 80 ℃ 초과 280 ℃ 이하인 것에 한정한다. 각 온도 퓨즈는 다음과 같이 표기한다.', '전기용품 표시사항 작성 가이드북', 41, '가이드북 2021-11', 0, 'auto'),
