INSERT INTO text_blocks (item_id, code, variant, show_if, title, lines, needs_review) VALUES
(1001, 'std_marks', 'default', NULL, '전기용품 안전기준에서 규정한 표시사항', '["■ 표시", "KC 60227-3의 부속서 A(규정) 및 KC 60245-3의 부속서", "1(규정)에 따른다.", "■ 전선의 표시", "a) 기호", "b) 제조자명 또는 그 약호", "c) 제조 년", "■ 포장의 표시", "a) 명칭 또는 그 기호", "b) 도체 지름 또는 공칭 단면적", "c) 전선의 색(포장이 투명하여 색을 식별할 수 있는 경우에는 제외)", "d) 길이", "e) 무게(드럼의 경우에는 총 무게도 병행 표시)", "f) 드럼의 회전방향(드럼의 경우네만 한함)", "g) 전선의 감긴 끝의 위치(드럼의 경우에만 적용)", "h) 제조자명 또는 그 약호", "i) 제조 년 월"]', 1),
(1001, 'display_method', 'default', NULL, '표시 방법·적용 비고', '["교류전압을 사용하는 제품에만 한정하며, 통신 및 데이터 전송을 목적으로만 사용하는 것은 제외한다."]', 1),
(1002, 'std_marks', 'default', NULL, '전기용품 안전기준에서 규정한 표시사항', '["■ 표시", "KC 60227-4 부속서 A(규정), KC 60227-6 부속서 B(규정),", "KC 60227-7 부속서 B(규정), KC 60245-4 부속서 1(규정),", "KC 60245-5 부속서 1(규정), KC 60245-6 부속서 1(규정), KC", "60245-7 부속서 1(규정), KC 60502-1 부속서 D(규정)에 따른다.", "■ 전선의 표시", "a) 기호", "b) 제조자명 또는 그 약호", "c) 제조 년", "■ 포장의 표시", "a) 종류 또는 그 기호", "b) 도체 지름 또는 공칭 단면적", "c) 전선의 색(포장이 투명하여 색을 식별할 수 있는 경우에는 제외)", "d) 길이", "e) 무게(드럼의 경우에는 총 무게도 병행 표시)", "f) 전선의 감긴 끝의 위치(드럼의 경우에만 적용)", "g) 제조자명 또는 그 약호 h) 제조 년 월", "KC 60702-2에 따른다.", "■ 포장 표시", "a) 이 규격의 표시", "b) 제조자 또는 공급자 확인 방법", "c) 밀봉 부분의 최대 및 최소 동작 온도", "d) 계획된 케이블 확인 방법 또는 표시", "e) 보호 도체의 사용 여부", "f) 마개 나선 줄(thread) 형태 및 크기"]', 1),
(1002, 'display_method', 'default', NULL, '표시 방법·적용 비고', '["교류전압을 사용하는 제품에만 한정하며, 통신 및 데이터 전송을 목적으로만 사용하는 것은 제외한다."]', 1),
(1003, 'std_marks', 'default', NULL, '전기용품 안전기준에서 규정한 표시사항', '["c) 길이", "d) 무게", "e) 제조자명 또는 그 약호", "f) 제조 년 월"]', 1),
(1003, 'display_method', 'default', NULL, '표시 방법·적용 비고', '["교류전압을 사용하는 제품에만 한정하며, 통신 및 데이터 전송을 목적으로만 사용하는 것은 제외한다."]', 1),
(1004, 'std_marks', 'default', NULL, '전기용품 안전기준에서 규정한 표시사항', '["따라 표시한다.", "- 코드셋과 상호 연결 코드셋이 전기 기구와 동일한 제조자가", "제작하지 않은 전기 기구 플러그나 플러그 커넥터 및 커넥", "터와 함께 납품되지 않은 경우, 완전 코드셋이나 상호", "연결 코드셋의 제조자나 책임 공급자의 성명, 상표명 또는", "식별 기호를 표시한다.", "- 이 표시는 포장에만 부착하는 것은 아니다.", "비고) 예를 들어 코드셋에 부착한 고리에 제조자 또는 책임", "공급자의 성명, 상표나 식별 기호를 붙일 수 있다.", "- II등급 기기 결선용 플러그, 커넥터, 코드셋이나 상호 연결", "코드셋에는 II등급 구조를 나타내는 기호(이중 사각형)를", "표시하지 않는다."]', 1),
(1004, 'display_method', 'default', NULL, '표시 방법·적용 비고', '["교류전압을 사용하는 제품에만 한정하며, 통신 및 데이터 전송을 목적으로만 사용하는 것은 제외한다."]', 1),
(1005, 'std_marks', 'default', NULL, '전기용품 안전기준에서 규정한 표시사항', '["(가이드북에 세부 항목 없음: 적용 KC 규격의 표시 조항 원문 확인 필요)"]', 1),
(1005, 'display_method', 'default', NULL, '표시 방법·적용 비고', '["교류전압을 사용하는 제품에만 한정하며, 통신 및 데이터 전송을 목적으로만 사용하는 것은 제외한다."]', 1),
(1006, 'std_marks', 'default', NULL, '전기용품 안전기준에서 규정한 표시사항', '["- 정격 전류(A) 또는 정격 형광등 부하 전류(AX)나 2개의 다른", "정격을 조합하였을 경우에는 양쪽 조합의 정격", "- 정격 전압(볼트)", "- 제조사 명, 판매자 명, 상호 또는 식별 기호", "- 전원의 성질 기호", "- 구조의 기호", "- 유해 영향에 대한 보호 등급", "- 조작 방법", "- 장착 방법", "- 단자 형태", "- 보호 등급", "- 형광등부하 전류가 부착된 표시", "■ 스위치의 중요 부분에 표시될 사항", "- 정격 전류, 정격 전압 및 전원의 특성", "- 제조자 또는 책임 있는 판매자의 명칭", "- 도체에서 제거해야할 절연의 길이", "- 미니 갭, 마이크로 갭 구조 또는 반도체 개폐 장치용", "- 기호가 사용될 경우 기호", "- 형번"]', 1),
(1006, 'display_method', 'default', NULL, '표시 방법·적용 비고', '["교류전압을 사용하는 제품에만 한정하며, 통신 및 데이터 전송을 목적으로만 사용하는 것은 제외한다."]', 1),
(1007, 'std_marks', 'default', NULL, '전기용품 안전기준에서 규정한 표시사항', '["■ 형식 참조 기호", "■ 주위온도의 한도값", "■ 단자의 형식", "■ 작동 주기 및 순서", "■ 신호 표시", "■ 회로 차단", "■ 절연 재료", "■ 보호 장치", "■ 조명 제어에 독점적으로 사용하는 코드 스위치에 “OFF”표", "시를 하지 않는다."]', 1),
(1007, 'display_method', 'default', NULL, '표시 방법·적용 비고', '["교류전압을 사용하는 제품에만 한정하며, 통신 및 데이터 전송을 목적으로만 사용하는 것은 제외한다."]', 1),
(1008, 'std_marks', 'default', NULL, '전기용품 안전기준에서 규정한 표시사항', '["■ 정격전류 또는 볼트 암페어 또는 와트 표기의 정격부하", "■ 전원에 대한 기호(심벌)", "■ 제조자 또는 책임 있는 공급자 이름", "■ 유형 참고사항(카탈로그 번호 등)", "■ 적용 시, 최소간격 구조에 대한 기호", "■ 적용 시, 극소간격 구조에 대한 기호", "■ 적용 시, 반도체 전환 장치에 대한 기호", "■ 고체 물질의 침투로 인한 위험요인에 대한 보호 등급의", "특성값 표기", "■ 액체 침투로 인한 위험요인에 대한 보호 등급의 특성값 표기"]', 1),
