INSERT INTO text_blocks (item_id, code, variant, show_if, title, lines, needs_review) VALUES
(1434, 'std_marks', 'default', NULL, '전기용품 안전기준에서 규정한 표시사항', '["(가이드북에 세부 항목 없음: 적용 KC 규격의 표시 조항 원문 확인 필요)"]', 1),
(1434, 'display_method', 'default', NULL, '표시 방법·적용 비고', '["정격입력이 1 kW 이하인 것에 한정한다."]', 1),
(1435, 'std_marks', 'default', NULL, '전기용품 안전기준에서 규정한 표시사항', '["(가이드북에 세부 항목 없음: 적용 KC 규격의 표시 조항 원문 확인 필요)"]', 1),
(1435, 'display_method', 'default', NULL, '표시 방법·적용 비고', '["정격입력이 1 kW 이하인 것에 한정한다."]', 1),
(1436, 'std_marks', 'default', NULL, '전기용품 안전기준에서 규정한 표시사항', '["(가이드북에 세부 항목 없음: 적용 KC 규격의 표시 조항 원문 확인 필요)"]', 1),
(1436, 'display_method', 'default', NULL, '표시 방법·적용 비고', '["기계기구류에 부착되는 특수구조인 것은 제외한다."]', 1),
(1437, 'std_marks', 'default', NULL, '전기용품 안전기준에서 규정한 표시사항', '["(가이드북에 세부 항목 없음: 적용 KC 규격의 표시 조항 원문 확인 필요)"]', 1),
(1438, 'std_marks', 'default', NULL, '전기용품 안전기준에서 규정한 표시사항', '["(가이드북에 세부 항목 없음: 적용 KC 규격의 표시 조항 원문 확인 필요)"]', 1),
(5001, 'caution', 'default', NULL, '사용상 주의사항', '["1. 적재하중 및 운행 속도에 적합한 공기압 유지", "2. 적정속도 준수(최대제한속도 60 km/h, 최대 연속주행시간", "3. 타이어가 가열된 상태에서 공기압 조정 금지", "4. 복륜으로 장착된 두 타이어의 공기압이 동일한지 항상 확인", "5. 도로상 이물질에 의한 충격 주의", "6. 적정한 브레이킹 시스템 유지 및 정기적인 차량 점검 실시", "7. 전륜 사용금지", "8. 타이어 마찰 최소화", "9. 과속, 과적 급제동 주의", "10. 급격한 코너링을 피하여 운행", "11. 운행조건에 알맞은 제품 사용"]', 1),
(5001, 'display_method', 'default', NULL, '표시 방법·적용 비고', '["폐타이어의 표시를 대용해도 좋다.", "레이디얼 타이어에는 RADIAL / 벨티드 바이어스 타이어에는 BELT, BELTS 또는 BELTED / 눈길용 타이어에는 SNOW / 경트럭용 타이어에는 ULTRA LIGHT TRUCK / 소형 트럭용 타이어에는 LIGHT TRUCK 또는 그 약호", "트레드 웨어 인디케이터(슬립사인) 타이어의 트레드 홈 깊이가 1.6 mm 까지 마모되었다는 것을 표시하는 트레드 웨어 인디케이터를, 승용차 및 경트럭용 재생타이어에 있어서는 원둘레 위의 4개소 이상에, 그 외의 재생타이어에 대해서는 6개소 이상에 넣어서 표시하여야 한다. 이 위치를 표시하는 기호(△표시)를 재생타이어 양쪽면에 재생타이어의 금형에 각인하여 표시할 수 있다.", "스노우타이어는 b에 표시한 것 이외에도 트레드의 홈 깊이가 50 % 까지 마모된 것을 표시하는 플레이트 포옴(plate form)을 타이어 원둘레 위의 4개소 이상 표시하여야 되며, 또한 그 위치를 표시하는 화살표(󰀺)를 타이어 양쪽면에 타이어의 금형에 각인 하여 표시할 수 있다.", "타이어 표면(사이드월, 숄더부 등)에 각인의 방법으로 눈에 띄게 표시하여야 한다.", "단, 2회 이상 재생 시, 재생횟수만큼 약호를 각인(예: 2회 재행 재 재 )"]', 1),
(5002, 'caution', 'default', NULL, '사용상 주의사항', '["1. 트레드 폴리 부분 해지 시 오염물질이 닿지 않게 주의하시기", "2. 트레드를 열어 가까이 하지 마시고 물에 접촉되지 않게"]', 1),
(5002, 'display_method', 'default', NULL, '표시 방법·적용 비고', '["트레드용 고무는 변질 및 상호 점착을 방지하기 위하여 매 권마다 셀로판, 폴리에틸렌 또는 기타 상호 점착이 되지 않는 재질의 필름을 사이에 끼워서 감아 포장하여 표시하여야 한다."]', 1),
(5003, 'caution', 'default', NULL, '사용상 주의사항', '["2. 노즐구멍이 막히지 않은 것을 확인한 후 사용하시오.", "3. 최대 조리량을 넘기지 마시오.", "4. 사용 전에 반드시 취급 설명서를 읽으시오.(눈에 뜨이게 표시)", "5. 고무패킹을 오랜시간 사용할 경우 수축되어 성능이 저하될", "6. 사용 전에 증기배출 구멍이 뚫린 것을 확인 후 사용하시오.", "7. 밥, 찜 외의 용도로 사용금지 특히, 삼계탕과 같은 점성이", "8. 가열하면 내부가 고온 고압상태가 되어 잘못 사용하면", "9. 꼭 사용 전에 사용설명서를 읽고 사용방법 및 주의사항에", "10. 기타 안전한 사용에 관한 주의, 경고", "1. 구조 및 성능 조리방법(최대 및 최소 조리량 포함)", "2. 사용상 주의사항", "3. 올바르고 안전한 제품사용 및 유지보전", "4. 사용설명서의 발간일자", "5. 기타 환경 및 자원의 보존 내용"]', 1),
(5003, 'display_method', 'default', NULL, '표시 방법·적용 비고', '["제품 또는 최소단위 포장마다 소비자가 보기 쉬운 곳에 쉽게 지워지지 않는 방법으로 표시함. 다만, 사용상 주의사항은 제품 또는 포장이외의 사용설명서 등에 별도 표시할 수 있으며, 주의사항의 위치, 내용 및 형태를 확실히 눈에 띄게 하여야 함. 사용 설명서", "제품마다 사용부주의로 인체에 위해를 방지하고 안전하게 사용할 수 있도록 카달로그(catalogue)나 사용설명서를 반드시 첨부 하여야 함.", "특정 작동순서가 안전하고 올바른 제품사용을 위해 필요한 경우 순서도를 사용할 수 있다."]', 1),
(5004, 'caution', 'default', NULL, '사용상 주의사항', '["1. 어린이들의 손에 닿지 않게 보관할 것", "2. 얼굴 등 화상주의", "3. 화재 주의", "4. 50 ℃ 이상 또는 장시간의 일광에 노출 시 폭발위험", "5. 구멍을 뚫거나 불 속에 던지면 폭발위험", "6. 자동차 실내에 절대 보관금지"]', 1),
(5004, 'display_method', 'default', NULL, '표시 방법·적용 비고', '["가스라이터 제품마다 표시한다.", "주위 글씨 등과 쉽게 구별되어 보이는 방법(예 : 적색글씨, 음양각 표시 또는 주위 글씨보다 훨씬 큰 글씨 등)으로 반드시 제품에 표시하여야 한다."]', 1),
(5005, 'caution', 'default', NULL, '사용상 주의사항', '["1. 구명기구가 아니라는 표시와 수영장이나 풀장 등 안전한", "2. 공기를 과하게 넣는 것은 파손의 원인이 되므로 공기를", "3. 몹시 더운 때는 선체가 무르게 될 때가 있지만 공기의", "4. 금지사항 뾰족한 바위, 뾰족한 자갈, 철조망 등 예리한", "5. 공기주입 후 공기누설이 있는지 반드시 확인하시오.", "6. 기타 안전한 사용에 관한 주의, 경고", "1. 사용재료명, 치수(mm) 내경 × 외경 및 사용상 주의사항", "2. 올바르고 안전한 제품 사용 및 유지보전에 필요한 모든"]', 1),
(5005, 'display_method', 'default', NULL, '표시 방법·적용 비고', '["제품 또는 최소단위 포장마다 소비자들이 보기 쉬운 곳에 쉽게 지워지지 않는 방법으로 표시한다.", "사용상 주의사항의 위치, 내용 및 형태를 확실히 눈에 띄게 하여야 한다. 사용 설명서", "사용 재료명, 치수(mm) 내경 × 외경 및 사용상 주의사항은 제품 또는 포장이외의 한글 사용설명서등에 별도 표시할 수 있으며, 사용설명서에는 올바르고 안전한 제품 사용 및 유지보전에 필요한 모든 정보와 사용설명서의 발간일자 기타 환경 및 자원의 보존내용이 제공되어야 한다."]', 1),
(5006, 'caution', 'default', NULL, '사용상 주의사항', '["1. 구명기구가 아니라는 표시와 수영장이나 풀장 등 안전한", "2. 공기를 과하게 넣는 것은 파손의 원인이 되므로 공기를", "3. 몹시 더운 때는 선체가 무르게 될 때가 있지만 공기의", "4. 금지사항 뾰족한 바위, 뾰족한 자갈, 철조망 등 예리한", "5. 공기주입 후 공기누설이 있는지 반드시 확인하시오.", "6. 기타 안전한 사용에 관한 주의, 경고(습기주의 등)"]', 1),
(5006, 'display_method', 'default', NULL, '표시 방법·적용 비고', '["제품 또는 최소단위 포장마다 소비자들이 보기 쉬운 곳에 쉽게 지워지지 않는 방법으로 표시한다.", "사용 재료명 및 사용상 주의사항은 제품 또는 포장 이외의 사용설명서 등에 별도 표시할 수 있다."]', 1),
(5007, 'caution', 'default', NULL, '사용상 주의사항', '["2. 수영보조용품을 사용하는 기능에 따라 착용하고 벗는 방법", "3. 보관 및 사후관리 절차", "4. 사용자의 사용목적에 따라 제품을 선택할 수 있도록 제품에", "5. 정보사항 및 경고 사항의 표시 크기는 10 × 5 cm 이상의", "1. 공기를 주입하는 수영보조용품에 공기를 주입하는 방법, 공기를"]', 1),
(5007, 'display_method', 'default', NULL, '표시 방법·적용 비고', '["각 제품에는 표시라벨이 있어야 하고 한글로 기록되어야 함", "표시는 모든 수영보조용품 표면에 표시되어야 함", "경고사항은 “경고”라는 제목은 길이가 7 mm 이상인 큰 문자로 인쇄하거나 양각으로 새겨 넣어야 함. 색상은 선택 가능하나 바탕색과 대칭되는 색상으로 하거나 튀어나온 형태로 인쇄하여 식별이 잘 되도록 해야 함.", "사용상 주의사항은 포장사항 또는 동봉하는 설명서에 포함되야 함."]', 1),
(5008, 'caution', 'default', NULL, '사용상 주의사항', '["1. 공기를 주입하는 수영보조용품에 공기를 주입하는 방법,", "2. 보관 및 사후관리 절차", "3. 보관용품의 특별한 성능을 발휘하기 위한 수영보조용품의", "4. 정보 및 경고사항"]', 1),
(5008, 'display_method', 'default', NULL, '표시 방법·적용 비고', '["각 제품에는 표시라벨이 있어야 하고 한글로 기록되어야 함", "표시는 모든 수영보조용품 표면에 표시되어야 함", "경고사항은 “경고”라는 제목은 길이가 5 mm 이상인 큰 문자로 인쇄하거나 양각으로 새겨 넣어야 함. 색상은 선택 가능하나 바탕색과 대칭되는 색상으로 하거나 튀어나온 형태로 인쇄하여 식별이 잘 되도록 해야 함.", "사용상 주의사항은 포장상자 또는 동봉하는 설명서에 포함되어야 함.", "정보사항 및 경고 사항의 표시크기는 10 × 5 cm 이상의 크기로 하며 글자의 크기는 1.5 mm 이상이여야 하며 “경고”라는 글자는 크기가 5 mm 이상이어야 함."]', 1),
(5009, 'caution', 'default', NULL, '사용상 주의사항', '["1. 어린이가 사용하지 않도록 관리 및 보관해야 합니다.", "2. 얼굴과 머리를 향하여 쏘면 안 됩니다.", "3. 눈이나 귀 옆에서 쏘면 안 됩니다.", "4. 탄환이 눈에 맞으면 실명할 수 있으니, 반드시 보안경을", "5. 비비탄총의 파괴력을 증가시키기 위하여 구조를 바꾸거나", "6. 탄환은 제조자가 공급하거나 추천한 것 이외의 제품을 사용", "7. 그 외 사용 중에 발생할 수 있는 잠재적인 위험사항", "1. 사용상 주의사항", "2. 그 외 사용 중에 발생할 수 있는 잠재적 위험사항"]', 1),
(5009, 'display_method', 'default', NULL, '표시 방법·적용 비고', '["제품 표면에는 제조(수입)자명 또는 그 약호와, 제품색과 구별되는 색상으로 15포인트 이상 글자 크기로 “만 14세 미만은 사용할 수 없음”이라고 표시하여야 함.", "단위 포장에는 소비자 눈에 가장 띄기 쉬운 곳에 쉽게 지워지지 않는 방법으로 한글로 표시하되, 사용연령은 15포인트 이상의 글자 크기로 주위 글씨 등과 쉽게 구별되어 보이는 방법(예 : 노란 바탕에 빨간 글씨, 음･양각등)으로 표시하여야 함.", "단위 포장의 가장 눈에 띄기 쉬운 곳에 쉽게 지워지지 않는 방법으로 노란 바탕에 빨간색의 선명한 문자로 다음의 표시를 하여야 함. 다만, 사용상 주의사항의 4의 보안경 의무착용 관련 문구는 다른 문구보다 최소 50 % 이상 더 크게 표시하여야 함.", "포장에는 눈에 띄기 쉬운 곳에 경고문을 명확하게 표시하여야 함. 경고단어 “경고”는 안전주의 상징 “ ” 앞에 있어야 함. 경고단어 “경고”는 경고 문구에서 다른 단어들보다 최소 50 % 이상 더 커야 함. 경고단어 “경고”는 주황색 배경에 검은색 글씨이어야 함 안전주의 상징 “ ”은 느낌표 주위에 정삼각형으로 구성됨. 안전주의 상징 “ ”은 경고단어와 같은 수평선에 있어야 함. 안전주의 상징의 높이는 경고단어 높이와 같거나 더 커야 함. 안전주의 상징의 짙은 삼각형은 검은색이고 느낌표 부분은 주황색이어야 함. 경고 문구는 하얀색 바탕에 검은색 글씨이거나 검은색 바탕에 하얀색 글씨이어야 한다.", "발사방해물(탄속제한장치) 부착 여부와 발사방해물(탄속제한장치) 부착 위치를 제품에 표시하여야 한다.", "제품에는 안전장치의 잠금과 해제를 나타내는 표시가 있어야 한다.", "사용설명서에는 사용연령층이 쉽게 이해할 수 있는 문구로 작성되야 한다."]', 1),
(5010, 'caution', 'default', NULL, '사용상 주의사항', '["1. 어린이가 사용하지 않도록 관리 및 보관해야 합니다.", "2. 얼굴과 머리를 향하여 쏘면 안 됩니다.", "3. 눈이나 귀 옆에서 쏘면 안 됩니다.", "4. 탄환이 눈에 맞으면 실명할 수 있으니, 반드시 보안경을", "5. 비비탄총의 파괴력을 증가시키기 위하여 구조를 바꾸거나", "6. 탄환은 제조자가 공급하거나 추천한 것 이외의 제품을 사용", "7. 어린이용품 판매점이 아닌 별도의 지정점에서만 판매하여야", "8. 그 외 사용 중에 발생할 수 있는 잠재적인 위험사항", "1. 사용상 주의사항", "2. 그 외 사용 중에 발생할 수 있는 잠재적 위험사항"]', 1),
(5010, 'display_method', 'default', NULL, '표시 방법·적용 비고', '["제품 표면에는 제조(수입)자명 또는 그 약호와, 제품색과 구별되는 색상으로 15포인트 이상 글자 크기로 “만 19세 미만은 사용할 수 없음”이라고 표시하여야 함.", "단위 포장에는 소비자 눈에 가장 띄기 쉬운 곳에 쉽게 지워지지 않는 방법으로 한글로 표시하되, 사용연령은 15포인트 이상의 글자 크기로 주위 글씨 등과 쉽게 구별되어 보이는 방법(예 : 노란 바탕에 빨간 글씨, 음･양각 등)으로 표시하여야 함.", "단위 포장의 가장 눈에 띄기 쉬운 곳에 쉽게 지워지지 않는 방법으로 노란 바탕에 빨간색의 선명한 문자로 다음의 표시를 하여야 함. 다만, 사용상 주의사항 4의 보안경 의무착용 관련 문구는 다른 문구보다 최소 50 % 이상 더 크게 표시하여야 함.", "포장에는 눈에 띄기 쉬운 곳에 경고문을 명확하게 표시하여야 함. 경고단어 “경고”는 안전주의 상징 “ ” 앞에 있어야 함. 경고단어 “경고”는 경고 문구에서 다른 단어들보다 최소 50 % 이상 더 커야 함. 경고단어 “경고”는 주황색 배경에 검은색 글씨이어야 함 안전주의 상징 “ ”은 느낌표 주위에 정삼각형으로 구성됨. 안전주의 상징 “ ”은 경고단어와 같은 수평선에 있어야 함. 안전주의 상징의 높이는 경고단어 높이와 같거나 더 커야 함. 안전주의 상징의 짙은 삼각형은 검은색이고 느낌표 부분은 주황색이어야 함. 경고 문구는 하얀색 바탕에 검은색 글씨이거나 검은색 바탕에 하얀색 글씨이어야 한다.", "발사방해물(탄속제한장치) 부착 여부와 발사방해물(탄속제한장치) 부착 위치를 제품에 표시하여야 한다.", "제품에는 안전장치의 잠금과 해제를 나타내는 표시가 있어야 한다.", "사용설명서에는 사용연령층이 쉽게 이해할 수 있는 문구로 작성되야 한다."]', 1),
(5011, 'caution', 'default', NULL, '사용상 주의사항', '["1. 바위의 각진 부분 등의 예각모양 또는 이에 준 하는 물체에", "2. 사용 이력카드에 로프의 사용이력을 기록 관리하며 로프의", "3. 사용횟수 또는 사용 년 수 등을 기준으로 한 일반적인", "4. 로프의 굵기 별 사용용도에 대한 주의사항(예 : 9 ㎜ 이하", "5. 사용과 보관 및 취급에 대한 주의 사항"]', 1),
(5011, 'display_method', 'default', NULL, '표시 방법·적용 비고', '["제품 또는 최소포장마다 쉽게 지워지지 않는 방법으로 알아보기 쉽게 표시하여야 함.", "사용상의 주의사항은 별도의 사용설명서가 있는 경우에 표기 가능."]', 1),
(5012, 'caution', 'default', NULL, '사용상 주의사항', '["2. 팽창식인 경우 충분히 팽창될 때까지 사용하지 말아야 한다", "1. “방석(또는 이와 유사한) 용도로 사용금지” 표시", "3. “특정 의류와 함께 사용하거나, 특정 환경에서는 그 성능이", "1. 팽창식인 경우 충분히 팽창될 때까지 사용하지 말아야 한다는", "2. 착용자가 사용 전에 그 성능을 확인해야 한다는 설명", "3. 바다의 상태, 온도(기온)제한 등과 같은 사용상의 적절한", "4. 교환부품 및 교체방법과 서비스와 유지보수 설명, 포장방법에", "5. 안전장비 및 기타의류와 관련된 장비로써의 호환성"]', 1),
(5012, 'display_method', 'default', NULL, '표시 방법·적용 비고', '["각 제품에는 표시라벨이 있어야 하고 주된 내용이 한글로 기록되어야 함.", "표시는 선명한 문자 또는 그림이 포함된 문자를 사용하여 식별이 용이하도록 표시하여야 하며, 구명복으로부 터 떨어지거나 지워지지 않도록 부착하여야 함.", "표시라벨의 식별표시는 최소 10회 이상의 손세탁에서도 지워지거나 변형이 없이 식별이 가능하여야 함.", "표시라벨의 크기는 150 mm × 100 mm 이상이어야 함.", "용도란에는 표에 해당 용도 부분을 다른 색깔로 표시하는 등 소비자가 용도를 쉽게 식별할 수 있도록 표시함.", "사용설명서 각 제품에는 사용설명서가 있어야 하고 주된 내용이 한글로 기록되어야 함."]', 1),
(5013, 'caution', 'default', NULL, '사용상 주의사항', '["1. “방석(또는 이와 유사한) 용도로 사용금지” 표시", "2. 팽창식인 경우 충분히 팽창될 때까지 사용하지 말아야", "3. “특정 의류와 함께 사용하거나, 특정 환경에서는 그 성능이", "4. “체중 30 kg 이하인 사람은 사용하지 말 것”", "1. 착용자가 사용 전에 그 성능을 확인해야 한다는 설명", "2. 바다의 상태, 온도(기온)제한 등과 같은 사용상의 적절한", "3. 교환부품 및 교체방법과 서비스와 유지보수 설명, 포장방법", "4. 안전장비 및 기타의류와 관련된 장비로써의 호환성"]', 1),
(5013, 'display_method', 'default', NULL, '표시 방법·적용 비고', '["각 제품에는 표시라벨이 있어야 하고 주된 내용이 한글로 기록되어야 함.", "표시는 선명한 문자 또는 그림이 포함된 문자를 사용하여 식별이 용이하도록 표시하여야 하며, 부력 보조복으로부터 떨어지거나 지워지지 않도록 부착하여야 함.", "표시라벨의 식별표시는 최소 10회 이상의 손 세탁에서도 지워지거나 변형이 없이 식별이 가능하여야 함.", "표시라벨의 크기는 150 mm × 100 mm 이상이어야 함.", "용도란에는 표에 해당 용도 부분을 다른 색깔로 표시하는 등 소비자가 용도를 쉽게 식별할 수 있도록 표시함."]', 1),
(5014, 'display_method', 'default', NULL, '표시 방법·적용 비고', '["몸체 또는 최소 단위 포장의 가장 눈에 띄기 쉬운 표면에 인쇄 또는 스티커로 다음 사항을 한글로 표시하여야 함. 다만, 극성은 제품 낱개에 표시하여야 함."]', 1),
(5015, 'caution', 'default', NULL, '사용상 주의사항', '["1. 취급 시에는 물, 기름 및 티끌이 혼입하지 않도록 한다.", "2. 독성이 있으므로 먹어서는 안된다.", "3. 먹었을 경우는 곧 토해내고 의사의 처방을 받아야 한다.", "4. 보존하는 경우는 자동차용 브레이크액이라는 표시가 있는", "5. 이 용기에 다른 브레이크액을 넣어서는 안 된다. 또 이", "6. 탱크의 보충은 자동차마다 규정되어 있는 브레이크액 점검"]', 1),
(5015, 'display_method', 'default', NULL, '표시 방법·적용 비고', '["제품 또는 최소단위 포장마다 보기 쉬운 곳에 쉽게 지워지지 않는 방법으로 표기한다.", "사용상 주의사항은 제품 또는 포장 이외의 사용설명서 등에 별도 표시할 수 있다.", "용기의 보기 쉬운 곳에 다음의 사항의 취지 내용을 표시 또는 첨부하여야 한다."]', 1),
(5016, 'caution', 'default', NULL, '사용상 주의사항', '["1. 타이어가 오래되었을 경우 갈라지는 등 안전에 문제가 발생", "2. 휠얼라이먼트 : 편마모 및 핸들쏠림을 방지하기 위해 타이어", "3. 타이어 공기압 체크 및 조정"]', 1),
(5016, 'display_method', 'default', NULL, '표시 방법·적용 비고', '["제품 또는 최소포장 단위 마다 보기 쉬운 곳에 쉽게 지워지지 않는 방법으로 표시함. 다만, b 및 c에 나타낸 사항을 타이어의 금형에 각인하여 표시하여야 한다.", "타이어의 호칭은 KS M 6750 부속서 I에 따른다.", "영문자의 경우는 대문자 또는 소문자로 표시한다.", "타이어의 호칭 또는 상품명 등에 의해 명확한 경우는 생략해도 좋다.", "타이어의 종류를 나타내는 문자는 다음에 따른다. 1) 레이디얼 타이어에는 RADIAL 2) 튜브리스 타이어에는 TUBELESS 3) 겨울용 타이어에는 SNOW, M＋S 또는 그에 준하는 문자 4) 응급용 타이어에는 응급용을 나타내는 문자 표시 및 T타입 응급용 타이어에는 사용 공기압을 나타내는 표시 5) 경트럭용 타이어에는 ULTRA LIGHT TRUCK 또는 그 약호 6) 소형 트럭용 타이어에는 LIGHT TRUCK 또는 그 약호 7) 트럭 및 버스용 타이어의 홈 깊이가 얕은 타이어에는 HIGHWAY TREAD－J 또는 그 약호 8) 트럭 및 버스용 타이어의 홈 깊이가 깊은 타이어에는 EXTRA HEAVY TREAD 또는 그 약호, 다만 바이어스 겨울용 타이어의 경우는 생략해도 된다."]', 1),
(5017, 'caution', 'default', NULL, '사용상 주의사항', '["1. 타일 표면은 장식을 위하여 모양을 붙이거나 또는 평면", "2. 정사각형 및 직사각형의 4모서리와 계단용의 뒷모서리는", "3. 모떼기 및 모서리용은 직사각형으로 할 수 있다.", "4. 계단용의 흠은 줄모양의 솟음으로 할 수 있다. 이 수는", "5. 그림에 나타내는 모양이 좌우 비대칭인 것은 그 대칭형도"]', 1),
(5017, 'display_method', 'default', NULL, '표시 방법·적용 비고', '["타일에는 제조자 명 또는 그 약호를 표시함", "다만, 제조 방법 때문에 곤란한 것은 이 규정에서 제외됨. 또, 구성 타일인 경우는 첨지에 표시할 수 있음.", "포장의 겉면에 표시함.", "부속서 4.1~4.4항 참조", "타일은 소지의 질, 표면 및 유약의 상태, 접착성(흡수율, 뒷면의 모양)에 따라 적합 유무를 카달로그, 설명서 등에 명확히 표시한다.", "또한 내동해성의 정도에 따라 한랭지 사용에 적합 여부를 표시하는 것이 좋다."]', 1),
(5018, 'caution', 'default', NULL, '사용상 주의사항', '["1. 핸드브레이크가 붙어있지 않기 때문에 경사길 등의 사용에", "2. 좌석을 사용하는 경우 반드시 주차용 스토퍼를 좌우 양바퀴", "3. 이 제품은 주로 고령자의 외출 때에 사용하는 제품으로", "1. 취급설명서를 반드시 읽고 읽은 후에는 보관할 것.", "2. 이제품은 주로 고령자가 외출할 때 보행이나 운반 및 휴식에", "3. 각부의 명칭(그림으로 표시할 것)", "4. 조립 또는 조절, 접이 등의 방법 또는 주의방법", "5. 주차용 스톱퍼 및 핸들 브레이크의 조작방법", "6. 좌석의 사용방법", "7. 가방 안에 유아를 실는 다든지, 좌석위에 사람을 실은 채", "8. 보관방법(비 맞지 않도록 등) 및 손질 방법", "9. 사용상의 주의", "10. 제원(각부의 치수, 중량 등)"]', 1),
(5018, 'display_method', 'default', NULL, '표시 방법·적용 비고', '["제품 또는 최소포장 단위 마다 소비자가 보기 쉬운 곳에 쉽게 지워지지 않는 방법으로 표시하여야 함.", "사용상 주의사항은 제품 또는 최소포장 단위 이외의 한글 사용설명서 등에 별도로 표시할 수 있음.", "알기 쉬운 내용으로 첨부한다. 단, 2에 대해서는 안전경고 표시를 해서 보다 알기 쉬운 것으로 할 것."]', 1),
(5019, 'caution', 'default', NULL, '사용상 주의사항', '["1. 취급 설명서를 반드시 읽은 후 보관할 것", "2. 각 부분의 명칭(그림으로 표시할 것)", "3. 조립 또는 조절 등의 방법 및 주의", "4. 보관방법 (비 맞게 하지 않을 것 등) 및 손질방법", "5. 사용상주의"]', 1),
(5019, 'display_method', 'default', NULL, '표시 방법·적용 비고', '["제품 또는 최소단위 포장마다 보기 쉬운 곳에 쉽게 지워지지 않는 방법으로 표시하여야 함.", "알기 쉬운 내용으로 첨부하여야 함."]', 1),
(5020, 'caution', 'default', NULL, '사용상 주의사항', '["1. 취급 설명서를 반드시 읽은 후 보관할 것", "2. 각 부분의 명칭(그림으로 표시할 것)", "3. 조립 또는 조절 등의 방법 및 주의", "4. 보관방법 (비 맞게 하지 않을 것 등) 및 손질방법", "5. 사용상주의"]', 1),
(5020, 'display_method', 'default', NULL, '표시 방법·적용 비고', '["제품 또는 최소단위 포장마다 보기 쉬운 곳에 쉽게 지워지지 않는 방법으로 표시하여야 함.", "알기 쉬운 내용으로 첨부하여야 함."]', 1),
(5021, 'caution', 'default', NULL, '사용상 주의사항', '["1. 취급 설명서를 반드시 읽은 후 보관할 것", "2. 각 부분의 명칭(그림으로 표시할 것)", "3. 조립 또는 조절 등의 방법 및 주의", "4. 보관방법 (비 맞게 하지 않을 것 등) 및 손질방법", "5. 사용상주의"]', 1),
(5021, 'display_method', 'default', NULL, '표시 방법·적용 비고', '["제품 또는 최소단위 포장마다 보기 쉬운 곳에 쉽게 지워지지 않는 방법으로 표시하여야 함.", "알기 쉬운 내용으로 첨부하여야 함."]', 1),
(5022, 'caution', 'default', NULL, '사용상 주의사항', '["1. 정격전압", "2. 역삽입시 건전지의 회로가 차단되지 않는 구조일 경우 다음", "3. 건전지의 수명이 끝난 경우 동시에 모든 전지를 교체하고", "4. 화재시 대비시험 중 온도센서형의 경우 센서동작 온도 표시", "5. 다음 사항을 적색 글자당 가로 세로 5 mm 이상으로 포장"]', 1),
(5022, 'display_method', 'default', NULL, '표시 방법·적용 비고', '["제품 또는 최소단위 포장마다 보기 쉬운 곳에 쉽게 지워지지 않는 방법으로 표시함.", "제품 본체(또는 최소 단위포장) 및 별도의 사용설명서에는 쉽게 지워지지 않고 소비자가 쉽게 식별할 수 있는 방법으로 표시하여야 함."]', 1),
(5023, 'display_method', 'default', NULL, '표시 방법·적용 비고', '["제품 또는 최소단위 포장마다 보기 쉬운 곳에 쉽게 지워지지 않는 방법으로 알아보기 쉽게 표시하여야 함."]', 1),
(5024, 'caution', 'default', NULL, '사용상 주의사항', '["1. 사용 후에는 물기를 제거한 후 보관할 것", "2. 보드바닥은 가끔 왁싱 해줄 것", "3. 엣지날이 무디어지면 날을 세워줄 것", "1. 사용 후에는 물기를 제거한 후 보관할 것", "2. 발에 꼭 맞는 부츠를 선택할 것(신어보고 몸을 앞으로 기울였", "3. 스노보드는 타기 전에 조임장치를 확실히 조인 후에 탈 것"]', 1),
(5024, 'display_method', 'default', NULL, '표시 방법·적용 비고', '["제품 또는 최소단위 포장마다 보기 쉬운 곳에 쉽게 지워지지 않는 방법으로 알아보기 쉽게 표시하여야 함.", "제품에는 쉽게 지워지지 않는 방법으로 표시하여야 함."]', 1),
(5025, 'caution', 'default', NULL, '사용상 주의사항', '["1. 경고", "2. 사용 시 안전보호장구(헬멧, 무릎 및 팔꿈치보호대, 손목보", "3. 미끄러움이 발생하기 쉬운 장소나 눈, 비가 올 때에는 타지 말 것", "4. 차도나 교통이 혼잡한 곳, 급경사진 곳 등 안전하지 못한", "5. 탑승자와 다른 사람에게 사고의 우려가 있는 포장도로나", "6. 젖어있거나 편평하지 않는 표면에서는 타지 말 것", "7. 새로운 기술을 포함하여 모든 것을 천천히 배울 것. 스케이트보", "8. 탑승 중의 안전사고 대부분은 골절이므로 처음에는 스케이", "9. 처음 배우는 사람은 친구나 보호자와 함께 탈 것.", "10. 스케이트보드 위에서 뛰어 내리기 전에 스케이트보드 진행", "1. 사용 전 안전상태 확인", "2. 임의 또는 불법 개조 금지", "3. 사용 시 안전보호장구 착용(안전모, 무릎 및 팔꿈치보호대,", "4. 기타 필요한 사항(위험한 장소의 사용금지, 도로교통법 준수 등)", "5. 합선보호, 과전류보호, 저전압보호 장치에 관한 내용", "6. 최대 주행 가능한 연속 주행거리", "7. 가속 및 브레이크 등 작동방법(전륜 및 후륜 브레이크에", "8. 계기판의 표시 내용에 대한 설명", "9. 배터리의 충전시간 등 정확한 사용과 유지방법, 충전기의", "10. 제품의 설명도와 전기단선도를 첨부", "11. 사용설명서를 자세히 읽고 제품의 기능을 이해하기 전에", "12. 배터리사양에 대한 설명(전압, 용량 등)", "13. 기타 제조업체에서 설명이 필요한 사항", "14. 스케이트보드 구조에 관한 정보 다음의 유의사항을 포함하", "15. 스케이트보드 조정장치가 있을 경우 그것이 올바르게 조정", "16. 점검과 유지보수에 대한 지시사항 장치의 안전성을 증대시"]', 1),
(5025, 'display_method', 'default', NULL, '표시 방법·적용 비고', '["제품 또는 최소단위 포장마다 보기 쉬운 곳에 쉽게 지워지지 않는 방법으로 알아보기 쉽게 표시하여야 함.", "사용상 주의사항은 제품본체(또는 최소 단위포장) 또는 사용설명서에 쉽게 지워지지 않고 소비자기", "경고문구는 제품의 낱개에 다음의 “ 경고” 헬멧 등 안전보호장구를 반드시 착용한 후", "“ 경고! 스케이드보드 위에서 달리거나 뛰지 말 것”"]', 1),
(5026, 'caution', 'default', NULL, '사용상 주의사항', '["1. 사용 전 안전상태 확인", "2. 임의 또는 불법 개조 금지", "3. 사용 시 안전보호장구 착용(안전모, 무릎 및 팔꿈치보호대,", "4. 기타 필요한 사항(위험한 장소의 사용금지, 도로교통법 준수 등)", "5. 합선보호, 과전류보호, 저전압보호 장치에 관한 내용", "6. 최대 주행 가능한 연속 주행거리", "7. 가속 및 브레이크 등 작동방법(전륜 및 후륜 브레이크에", "8. 계기판의 표시 내용에 대한 설명", "9. 배터리의 충전시간 등 정확한 사용과 유지방법, 충전기의", "10. 제품의 설명도와 전기단선도를 첨부", "1. 경고", "2. 사용 시 안전보호장구(헬멧, 무릎 및 팔꿈치보호대, 손목보", "3. 미끄러움이 발생하기 쉬운 장소나 눈, 비가 올 때에는 타지 말 것", "4. 차도나 교통이 혼잡한 곳, 급경사진 곳 등 안전하지 못한", "5. 탑승자와 다른 사람에게 사고의 우려가 있는 포장도로나", "6. 젖어있거나 편평하지 않는 표면에서는 타지 말 것", "11. 사용설명서를 자세히 읽고 제품의 기능을 이해하기 전에", "12. 배터리사양에 대한 설명(전압, 용량 등)", "13. 기타 제조업체에서 설명이 필요한 사항"]', 1),
